package com.primehr.performancemanagement.application;
import com.primehr.config.PrimeHrProperties;import com.primehr.integration.administrative.PermissionDataScope;import com.primehr.performancemanagement.api.PerformanceAppealDtos.*;import com.primehr.performancemanagement.domain.*;import com.primehr.performancemanagement.infrastructure.*;import com.primehr.rsp.applicant.storage.DocumentStorage;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.io.*;import java.nio.file.Path;import java.security.*;import java.time.*;import java.util.*;
@Service@Transactional public class PerformanceAppealServiceImpl implements PerformanceAppealService{
 private final PerformanceFinalRatingRepository finals;private final PerformanceRatingAcknowledgmentRepository acknowledgments;private final PerformanceRatingAppealRepository appeals;private final PerformanceAppealEvidenceRepository evidence;private final PerformanceRatingCaseRepository ratingCases;private final PerformancePolicyVersionRepository policies;private final PerformanceCycleMilestoneRepository milestones;private final PerformanceManagementTeamRepository teams;private final PerformanceManagementTeamMemberRepository members;private final PerformanceRatingActionRepository actions;private final PerformanceRatingService ratingService;private final PerformanceInterventionService interventions;private final DocumentStorage storage;private final PrimeHrProperties properties;private final PrimeHrAuditService audit;
 public PerformanceAppealServiceImpl(PerformanceFinalRatingRepository f,PerformanceRatingAcknowledgmentRepository ack,PerformanceRatingAppealRepository ap,PerformanceAppealEvidenceRepository e,PerformanceRatingCaseRepository rc,PerformancePolicyVersionRepository p,PerformanceCycleMilestoneRepository m,PerformanceManagementTeamRepository t,PerformanceManagementTeamMemberRepository mm,PerformanceRatingActionRepository a,PerformanceRatingService rs,PerformanceInterventionService i,DocumentStorage ds,PrimeHrProperties pp,PrimeHrAuditService au){finals=f;acknowledgments=ack;appeals=ap;evidence=e;ratingCases=rc;policies=p;milestones=m;teams=t;members=mm;actions=a;ratingService=rs;interventions=i;storage=ds;properties=pp;audit=au;}
 @Override@Transactional(readOnly=true)public List<FinalRatingView>finalRatings(String agency,String actor,PermissionDataScope scope){return ratingCases.findByAgencyIdOrderByOpenedAtDesc(agency).stream().filter(c->visible(c,actor,scope)).flatMap(c->finals.findByAgencyIdAndRatingCaseIdOrderByRevisionNoAsc(agency,c.getId()).stream()).map(this::finalView).toList();}
 @Override public AcknowledgmentResponse acknowledge(String agency,String finalId,AcknowledgeInput in,String actor,PermissionDataScope scope,String correlation){PerformanceFinalRating rating=finalRating(agency,finalId);PerformanceRatingCase c=ratingCase(agency,rating.getRatingCaseId());if(!c.getOwnerEmployeeNo().equalsIgnoreCase(actor)||scope!=PermissionDataScope.OWN_RECORDS&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Only the rating owner may acknowledge receipt");requiredPolicy(agency,c,true);window(agency,c.getCycleId(),PerformanceCycleMilestone.Type.ACKNOWLEDGMENT_DUE,in.overrideWindow(),in.reason());var existing=acknowledgments.findByAgencyIdAndFinalRatingId(agency,finalId);if(existing.isPresent())return acknowledgment(existing.get());PerformanceRatingAcknowledgment value=acknowledgments.saveAndFlush(new PerformanceRatingAcknowledgment(agency,finalId,c.getId(),c.getOwnerEmployeeNo(),in.response(),actor,Instant.now()));record(agency,c.getId(),value.getId(),"ACKNOWLEDGE_FINAL_RATING",in.idempotencyKey(),actor,in.reason());AcknowledgmentResponse after=acknowledgment(value);audit.record(agency,"ACKNOWLEDGE_FINAL_RATING","SPMS_RATING_ACKNOWLEDGMENT",value.getId(),rating.getRevisionNo(),value.getVersion(),null,after,in.reason(),correlation);return after;}
 @Override public AcknowledgmentResponse closeWithoutAcknowledgment(String agency,String finalId,ActionInput in,String actor,PermissionDataScope scope,String correlation){if(scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Agency-wide permission is required to close without acknowledgment");PerformanceFinalRating rating=finalRating(agency,finalId);PerformanceRatingCase c=ratingCase(agency,rating.getRatingCaseId());requiredPolicy(agency,c,true);requirePmt(agency,c,actor);if(in.reason()==null||in.reason().isBlank())throw new IllegalArgumentException("Closure reason is required");var existing=acknowledgments.findByAgencyIdAndFinalRatingId(agency,finalId);if(existing.isPresent())return acknowledgment(existing.get());PerformanceRatingAcknowledgment value=acknowledgments.saveAndFlush(PerformanceRatingAcknowledgment.close(agency,finalId,c.getId(),c.getOwnerEmployeeNo(),in.reason(),actor,Instant.now()));record(agency,c.getId(),value.getId(),"CLOSE_WITHOUT_ACKNOWLEDGMENT",in.idempotencyKey(),actor,in.reason());AcknowledgmentResponse after=acknowledgment(value);audit.record(agency,"CLOSE_FINAL_RATING_WITHOUT_ACKNOWLEDGMENT","SPMS_RATING_ACKNOWLEDGMENT",value.getId(),rating.getRevisionNo(),value.getVersion(),null,after,in.reason(),correlation);return after;}
 @Override public AppealResponse create(String agency,String finalId,AppealInput in,String actor,PermissionDataScope scope,String correlation){PerformanceFinalRating rating=finalRating(agency,finalId);PerformanceRatingCase c=ratingCase(agency,rating.getRatingCaseId());if(!c.getOwnerEmployeeNo().equalsIgnoreCase(actor)||scope!=PermissionDataScope.OWN_RECORDS&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Only the rating owner may file an appeal");requiredPolicy(agency,c,false);latest(agency,c,rating);PerformanceRatingAction prior=prior(agency,c.getId(),in.idempotencyKey());if(prior!=null)return response(agency,appeal(agency,prior.getSubjectId()));var existing=appeals.findByAgencyIdAndFinalRatingId(agency,finalId);if(existing.isPresent())return response(agency,existing.get());PerformanceRatingAppeal value=appeals.saveAndFlush(new PerformanceRatingAppeal(agency,finalId,c.getId(),c.getOwnerEmployeeNo(),in.grounds(),in.requestedRemedy()));record(agency,c.getId(),value.getId(),"CREATE_RATING_APPEAL",in.idempotencyKey(),actor,null);return audited(agency,value,"CREATE_PERFORMANCE_RATING_APPEAL",correlation);}
 @Override public AppealResponse edit(String agency,String id,AppealEdit in,String actor,PermissionDataScope scope,String correlation){PerformanceRatingAppeal value=appeal(agency,id);owner(value,actor,scope);check(value.getVersion(),in.recordVersion());value.update(in.grounds(),in.requestedRemedy());return audited(agency,appeals.saveAndFlush(value),"EDIT_PERFORMANCE_RATING_APPEAL",correlation);}
 @Override public AppealResponse submit(String agency,String id,ActionInput in,String actor,PermissionDataScope scope,String correlation){PerformanceRatingAppeal value=appeal(agency,id);owner(value,actor,scope);PerformanceRatingAction prior=prior(agency,value.getRatingCaseId(),in.idempotencyKey());if(prior!=null)return response(agency,value);check(value.getVersion(),in.recordVersion());PerformanceRatingCase c=ratingCase(agency,value.getRatingCaseId());requiredPolicy(agency,c,false);window(agency,c.getCycleId(),PerformanceCycleMilestone.Type.APPEAL_DUE,in.overrideWindow(),in.reason());value.submit(Instant.now());value=appeals.saveAndFlush(value);record(agency,c.getId(),value.getId(),"SUBMIT_RATING_APPEAL",in.idempotencyKey(),actor,in.reason());return audited(agency,value,"SUBMIT_PERFORMANCE_RATING_APPEAL",correlation);}
 @Override public AppealResponse decide(String agency,String id,AppealDecision in,String actor,PermissionDataScope scope,String correlation){if(scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Agency-wide appeal decision permission is required");PerformanceRatingAppeal value=appeal(agency,id);PerformanceRatingAction prior=prior(agency,value.getRatingCaseId(),in.idempotencyKey());if(prior!=null)return response(agency,value);check(value.getVersion(),in.recordVersion());PerformanceRatingCase c=ratingCase(agency,value.getRatingCaseId());requirePmt(agency,c,actor);if(value.getAppellantEmployeeNo().equalsIgnoreCase(actor)||c.getSupervisorEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Rating subject and assigned rater cannot decide the appeal");PerformanceFinalRating successor=null;if(in.outcome()==PerformanceRatingAppeal.Status.MODIFIED){if(in.items()==null||in.items().isEmpty())throw new IllegalArgumentException("Modified appeal requires complete recalculation inputs");var assessment=ratingService.createAppealAssessment(agency,c.getId(),in.reason(),in.items(),actor,correlation);PerformanceRatingAssessment source=ratingService.assessmentEntity(agency,assessment.id());PerformanceFinalRating priorFinal=finalRating(agency,value.getFinalRatingId());latest(agency,c,priorFinal);successor=finals.saveAndFlush(new PerformanceFinalRating(agency,c.getId(),priorFinal.getRevisionNo()+1,priorFinal.getId(),priorFinal.getCalibrationCaseId(),source,actor,Instant.now()));interventions.evaluate(agency,successor,actor,correlation);}else if(in.items()!=null&&!in.items().isEmpty())throw new IllegalArgumentException("Recalculation inputs are allowed only for a MODIFIED outcome");value.decide(in.outcome(),in.reason(),successor==null?null:successor.getId(),actor,Instant.now());value=appeals.saveAndFlush(value);record(agency,c.getId(),value.getId(),"DECIDE_RATING_APPEAL_"+in.outcome(),in.idempotencyKey(),actor,in.reason());return audited(agency,value,"DECIDE_PERFORMANCE_RATING_APPEAL",correlation);}
 @Override@Transactional(readOnly=true)public List<AppealResponse>list(String agency,String actor,PermissionDataScope scope){return appeals.findByAgencyIdOrderByCreatedAtDesc(agency).stream().filter(x->scope==PermissionDataScope.AGENCY_WIDE||scope==PermissionDataScope.OWN_RECORDS&&x.getAppellantEmployeeNo().equalsIgnoreCase(actor)||scope==PermissionDataScope.ASSIGNED_RECORDS&&ratingCase(agency,x.getRatingCaseId()).getSupervisorEmployeeNo().equalsIgnoreCase(actor)).map(x->response(agency,x)).toList();}
 @Override public EvidenceResponse upload(String agency,String id,String key,MultipartFile file,String actor,PermissionDataScope scope,String correlation){PerformanceRatingAppeal value=appeal(agency,id);owner(value,actor,scope);if(value.getStatus()!=PerformanceRatingAppeal.Status.DRAFT)throw new IllegalStateException("Evidence may be added only to a draft appeal");PerformanceRatingAction prior=prior(agency,value.getRatingCaseId(),key);if(prior!=null)return evidenceResponse(evidence.findByIdAndAgencyId(prior.getSubjectId(),agency).orElseThrow());if(!properties.storage().enabled())throw new IllegalStateException("Document uploads are disabled");if(file==null||file.isEmpty()||file.getSize()>properties.storage().maximumBytes())throw new IllegalArgumentException("Evidence size is invalid");String media=Objects.requireNonNullElse(file.getContentType(),"");if(!properties.storage().allowedMediaTypes().contains(media))throw new IllegalArgumentException("Evidence media type is not allowed");byte[] bytes;try{bytes=file.getBytes();}catch(IOException e){throw new IllegalArgumentException("Evidence could not be read",e);}verifySignature(media,bytes);String filename=safeFilename(file.getOriginalFilename());String objectKey=agency+"/performance-appeals/"+id+"/"+UUID.randomUUID().toString().replace("-","");storage.put(objectKey,bytes,media);try{PerformanceAppealEvidence saved=evidence.saveAndFlush(new PerformanceAppealEvidence(agency,id,filename,storage.provider(),objectKey,media,bytes.length,sha256(bytes),actor,Instant.now()));record(agency,value.getRatingCaseId(),saved.getId(),"UPLOAD_APPEAL_EVIDENCE",key,actor,null);EvidenceResponse after=evidenceResponse(saved);audit.record(agency,"UPLOAD_PERFORMANCE_APPEAL_EVIDENCE","SPMS_RATING_APPEAL_EVIDENCE",saved.getId(),1,saved.getVersion(),null,after,null,correlation);return after;}catch(RuntimeException e){storage.delete(objectKey);throw e;}}
 @Override@Transactional(readOnly=true)public EvidenceContent download(String agency,String appealId,String evidenceId,String actor,PermissionDataScope scope,String correlation){PerformanceRatingAppeal value=appeal(agency,appealId);access(value,actor,scope);PerformanceAppealEvidence stored=evidence.findByIdAndAgencyId(evidenceId,agency).orElseThrow(()->new ResourceNotFoundException("Appeal evidence not found"));if(!stored.getAppealId().equals(appealId))throw new ResourceNotFoundException("Appeal evidence not found");audit.record(agency,"DOWNLOAD_PERFORMANCE_APPEAL_EVIDENCE","SPMS_RATING_APPEAL_EVIDENCE",evidenceId,null,stored.getVersion(),null,Map.of("appealId",appealId,"checksum",stored.getChecksum()),null,correlation);return new EvidenceContent(stored.getOriginalFilename(),stored.getMediaType(),stored.getByteSize(),storage.get(stored.getStorageObjectKey()));}
 private void requiredPolicy(String agency,PerformanceRatingCase c,boolean acknowledgment){PerformancePolicyVersion p=policies.findByIdAndAgencyId(c.getPolicyVersionId(),agency).orElseThrow(()->new ResourceNotFoundException("Performance policy not found"));if(acknowledgment&&!p.isRequiresAcknowledgment()||!acknowledgment&&!p.isRequiresAppeal())throw new IllegalStateException("The exact performance policy does not require this action");}private void window(String a,String cycle,PerformanceCycleMilestone.Type type,boolean override,String reason){PerformanceCycleMilestone m=milestones.findByAgencyIdAndCycleIdOrderByDisplayOrderAsc(a,cycle).stream().filter(x->x.getType()==type).findFirst().orElseThrow(()->new IllegalArgumentException(type+" milestone is required"));Instant now=Instant.now(),end=m.getEndsAt()==null?m.getStartsAt():m.getEndsAt();if((now.isBefore(m.getStartsAt())||now.isAfter(end))&&!override)throw new IllegalArgumentException("Action is outside the configured "+type+" window");if(override&&(reason==null||reason.isBlank()))throw new IllegalArgumentException("A window override reason is required");}
 private void requirePmt(String agency,PerformanceRatingCase c,String actor){LocalDate day=LocalDate.now(ZoneId.of("Asia/Manila"));List<PerformanceManagementTeam> active=teams.findAll().stream().filter(x->x.getAgencyId().equals(agency)&&x.effectiveOn(day)).toList();if(active.size()!=1)throw new IllegalStateException("Exactly one effective PMT is required");boolean allowed=members.findByAgencyIdAndPmtIdOrderByEffectiveFromAscRoleAscEmployeeNoAsc(agency,active.get(0).getId()).stream().anyMatch(x->x.effectiveOn(day)&&x.isVoting()&&x.getRole()!=PerformanceManagementTeamMember.Role.SECRETARIAT&&x.getRole()!=PerformanceManagementTeamMember.Role.TECHNICAL_SUPPORT&&x.getEmployeeNo().equalsIgnoreCase(actor)&&!x.getEmployeeNo().equalsIgnoreCase(c.getOwnerEmployeeNo())&&!x.getEmployeeNo().equalsIgnoreCase(c.getSupervisorEmployeeNo()));if(!allowed)throw new AccessDeniedException("An effective non-conflicted voting PMT member is required");}
 private void latest(String a,PerformanceRatingCase c,PerformanceFinalRating f){PerformanceFinalRating latest=finals.findTopByAgencyIdAndRatingCaseIdOrderByRevisionNoDesc(a,c.getId()).orElseThrow();if(!latest.getId().equals(f.getId()))throw new IllegalStateException("Only the current final-rating revision may be appealed or modified");}private boolean visible(PerformanceRatingCase c,String actor,PermissionDataScope scope){return scope==PermissionDataScope.AGENCY_WIDE||scope==PermissionDataScope.OWN_RECORDS&&c.getOwnerEmployeeNo().equalsIgnoreCase(actor)||scope==PermissionDataScope.ASSIGNED_RECORDS&&c.getSupervisorEmployeeNo().equalsIgnoreCase(actor);}private void owner(PerformanceRatingAppeal x,String actor,PermissionDataScope scope){if(!x.getAppellantEmployeeNo().equalsIgnoreCase(actor)||scope!=PermissionDataScope.OWN_RECORDS&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Only the appellant may modify this appeal");}private void access(PerformanceRatingAppeal x,String actor,PermissionDataScope scope){if(scope==PermissionDataScope.AGENCY_WIDE)return;PerformanceRatingCase c=ratingCase(x.getAgencyId(),x.getRatingCaseId());if(scope==PermissionDataScope.OWN_RECORDS&&x.getAppellantEmployeeNo().equalsIgnoreCase(actor)||scope==PermissionDataScope.ASSIGNED_RECORDS&&c.getSupervisorEmployeeNo().equalsIgnoreCase(actor))return;throw new AccessDeniedException("Appeal is outside the permitted scope");}
 private FinalRatingView finalView(PerformanceFinalRating x){return new FinalRatingView(x.getId(),x.getRatingCaseId(),x.getRevisionNo(),x.getSupersedesId(),x.getSourceAssessmentId(),x.getRawScore(),x.getRoundedScore(),x.getRatingBandId(),x.getRatingLabel(),x.getCalculationFingerprint(),x.getFinalizedBy(),x.getFinalizedAt(),x.getVersion(),acknowledgments.findByAgencyIdAndFinalRatingId(x.getAgencyId(),x.getId()).map(this::acknowledgment).orElse(null));}private AcknowledgmentResponse acknowledgment(PerformanceRatingAcknowledgment x){return new AcknowledgmentResponse(x.getId(),x.getFinalRatingId(),x.getRatingCaseId(),x.getEmployeeNo(),x.getStatus().name(),x.getEmployeeResponse(),x.getClosureReason(),x.getActedBy(),x.getActedAt(),x.getVersion());}private AppealResponse response(String a,PerformanceRatingAppeal x){return new AppealResponse(x.getId(),x.getFinalRatingId(),x.getRatingCaseId(),x.getAppellantEmployeeNo(),x.getGrounds(),x.getRequestedRemedy(),x.getStatus().name(),x.getSubmittedAt(),x.getDecidedBy(),x.getDecidedAt(),x.getDecisionReason(),x.getSuccessorFinalRatingId(),x.getVersion(),evidence.findByAgencyIdAndAppealIdOrderByUploadedAtAsc(a,x.getId()).stream().map(this::evidenceResponse).toList());}private EvidenceResponse evidenceResponse(PerformanceAppealEvidence x){return new EvidenceResponse(x.getId(),x.getOriginalFilename(),x.getMediaType(),x.getByteSize(),x.getChecksum(),x.getUploadedBy(),x.getUploadedAt());}private AppealResponse audited(String a,PerformanceRatingAppeal x,String action,String correlation){AppealResponse after=response(a,x);audit.record(a,action,"SPMS_RATING_APPEAL",x.getId(),1,x.getVersion(),null,after,null,correlation);return after;}
 private PerformanceFinalRating finalRating(String a,String id){return finals.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Final rating not found"));}private PerformanceRatingCase ratingCase(String a,String id){return ratingCases.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance rating case not found"));}private PerformanceRatingAppeal appeal(String a,String id){return appeals.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance rating appeal not found"));}private PerformanceRatingAction prior(String a,String c,String key){return actions.findByAgencyIdAndRatingCaseIdAndRequestKey(a,c,key).orElse(null);}private void record(String a,String c,String subject,String type,String key,String actor,String reason){if(prior(a,c,key)==null)actions.save(new PerformanceRatingAction(a,c,subject,type,key,actor,reason,Instant.now()));}private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Expected recordVersion "+expected+" but current version is "+actual);}private static String safeFilename(String value){String name=value==null?"evidence":Path.of(value).getFileName().toString();return name.replaceAll("[^A-Za-z0-9._ -]","_");}private static String sha256(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}private static void verifySignature(String media,byte[] b){boolean ok=switch(media){case"application/pdf"->b.length>4&&b[0]=='%'&&b[1]=='P'&&b[2]=='D'&&b[3]=='F';case"image/png"->b.length>8&&(b[0]&255)==137&&b[1]=='P'&&b[2]=='N'&&b[3]=='G';case"image/jpeg"->b.length>3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255;default->false;};if(!ok)throw new IllegalArgumentException("Evidence content does not match its media type");}
}
